#include "DomainEventCatalogue.hpp"
namespace elysium::simulation {bool DomainEventCatalogue::addSchema(EventSchema s,std::string&w){if(!s.type||!s.version||!s.producerOwner){w="invalid event schema";return false;}return schemas_.emplace(s.type,std::move(s)).second;}bool DomainEventCatalogue::validate(const DomainEvent&e,std::string&w)const{auto i=schemas_.find(e.type);if(i==schemas_.end()){w="unknown event type";return false;}if(!e.id||e.version>i->second.version){w="unsupported event version";return false;}return true;}std::vector<DomainEvent>DomainEventCatalogue::order(std::vector<DomainEvent>v)const{std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.epoch==b.epoch?(a.orderKey==b.orderKey?a.id<b.id:a.orderKey<b.orderKey):a.epoch<b.epoch;});return v;}}
